#include "dfre/mission_df_socket.hpp"
#include <array>
#include <iostream>
#include <sstream>
#include <unordered_map>
using namespace dfre;
int main(){try{std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);std::uint32_t h[21];for(auto& x:h){std::uint64_t n;if(!(in>>n))throw MissionClientStartupError("Short socket fixture");x=std::uint32_t(n);}std::unordered_map<std::uint32_t,std::uint8_t> memory;const auto put=[&](auto at,unsigned width,auto n){for(unsigned i=0;i<width;++i)memory[at+i]=std::uint8_t(n>>(8*i));};const auto get=[&](auto at,unsigned width=4){std::uint32_t n=0;for(unsigned i=0;i<width;++i)n|=std::uint32_t(memory[at+i])<<(8*i);return n;};for(unsigned i=0;i<h[19];++i){std::uint32_t a,w,n;if(!(in>>a>>w>>n))throw MissionClientStartupError("Short socket memory");put(a,w,n);}struct Input{std::uint32_t site,size;std::vector<std::uint8_t> bytes;};std::vector<Input> frames;for(unsigned i=0;i<h[20];++i){Input f;if(!(in>>f.site>>f.size))throw MissionClientStartupError("Short socket frame");for(unsigned j=0;j<f.size;++j){unsigned n;if(!(in>>n))throw MissionClientStartupError("Short frame bytes");f.bytes.push_back(std::uint8_t(n));}frames.push_back(std::move(f));}unsigned cursor=0,depth=0,attempts=0;std::ostringstream trace;MissionDfSocketBindings b;const auto stack=[](auto at){return at>=0x1300000u&&at<0x1310000u;};const auto norm=[&](auto n){return stack(n)?0x30000000u+(n-0x1300000u):n;};
b.frame=[&](auto site,auto size,const auto& arguments){const auto& f=frames.at(cursor++);if(f.site!=site||f.size!=size)throw MissionClientStartupError("Socket frame differs");const auto at=0x1300000u+depth++*0x100u;for(unsigned i=0;i<size;++i)put(at+i,1,f.bytes.at(i));if(!arguments.empty())put(at,4,arguments.at(0));return at;};b.release=[&](auto,auto,auto){--depth;};
b.read=[&](auto at,auto width){const auto n=get(at,width);if(!stack(at))trace<<'R'<<at<<','<<width<<','<<n<<';';return n;};b.write=[&](auto at,auto width,auto n){if(!stack(at))trace<<'W'<<at<<','<<width<<','<<n<<';';put(at,width,n);};
b.before_call=[&](auto site,const auto& args){trace<<'C'<<site;for(auto n:args)trace<<','<<norm(n);trace<<';';if(site==h[16])put(h[17],4,h[18]);};
b.call=[&](auto site,const auto& args)->std::uint32_t{unsigned bytes=0,address=0;if(site==0x4c55b6){address=args.at(1);bytes=16;}if(site==0x4c55c2){address=args.at(2);bytes=4;}if(site==0x4c55ce||site==0x4c55d4){address=args.at(3);bytes=4;}if(bytes){trace<<'B'<<site;for(unsigned i=0;i<bytes;++i)trace<<','<<get(address+i,1);if(site==0x4c55d4)trace<<','<<get(args.at(4));trace<<';';}
switch(site){case 0x4c55f8:return h[4];case 0x4c55c8:return h[5]?0xffffffffu:77;case 0x4c55c2:return h[6]?0xffffffffu:0;case 0x4c55bc:return ((args.at(0)&255)<<8)|((args.at(0)>>8)&255);case 0x4c55b6:return attempts++<h[7]?0xffffffffu:0;case 0x4c55e0:return h[8];case 0x4c55ce:return h[9]?0xffffffffu:0;case 0x4c55d4:if(h[10])return 0xffffffffu;put(args.at(3),4,args.at(2)==0x1001?h[11]:h[12]);return 0;case 0x49dc80:return h[13];case 0x4c55b0:return h[14];case 0x4c55ec:return h[15];default:throw MissionClientStartupError("Unknown socket service");}};
std::uint32_t result=0;switch(h[0]){case 0:result=mission_df_socket_start(b,h[1],h[2],h[3]);break;case 1:result=mission_df_socket_buffers(b);break;case 2:result=mission_df_socket_open_send(b,h[1]);break;case 3:result=mission_df_socket_open_receive(b,h[1],h[2]);break;case 4:result=mission_df_socket_set_buffer(b,false,h[1]);break;case 5:result=mission_df_socket_set_buffer(b,true,h[1]);break;case 6:result=mission_df_socket_get_buffer(b,false);break;case 7:result=mission_df_socket_get_buffer(b,true);break;case 8:result=mission_df_socket_resolve(b,h[1]);break;default:throw MissionClientStartupError("Unknown socket operation");}if(cursor!=frames.size()||depth)throw MissionClientStartupError("Socket frames remain");std::cout<<result<<' '<<trace.str()<<'\n';}}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
